//! 🔺️ move-animation leaf-owned typed sparse operation diff.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfAnimation;
use crate::artifacts::gltf::schema::diff::GltfDiff;
use crate::artifacts::gltf::schema::mutations::move_animation::mutation::{apply, validate, GltfMoveAnimationPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{animations_op, family_diff, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.move-animation.v1";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfMoveAnimationOperation { Insert { position: usize, item: GltfAnimation }, Delete { index: usize, removed: GltfAnimation }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfMoveAnimationDiff { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfMoveAnimationPayload, pub operation: GltfMoveAnimationOperation }
async fn operation(payload: &GltfMoveAnimationPayload, base: &GltfSnapshot) -> GltfMoveAnimationOperation { GltfMoveAnimationOperation::Move { index: payload.index, position: payload.position } }
async fn touched_paths(payload: &GltfMoveAnimationPayload) -> Vec<String> { vec![format!("document/animations/{}", payload.index), format!("document/animations/{}", payload.position)] }
pub async fn validate_diff(diff: &GltfMoveAnimationDiff, base: &GltfSnapshot) -> Result<(), GltfTopLevelMutationRejection> { if diff.id != ID || diff.version != 1 { return Err(reject("gltf.mutation.invalid-diff-envelope", "diff", "descriptor identity does not match")); } if diff.touched_paths != touched_paths(&diff.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "diff/touchedPaths", "paths must be concrete payload-derived locations")); } validate(&diff.payload, base)?; if diff.operation != operation(&diff.payload, base) { return Err(reject("gltf.mutation.invalid-sparse-operation", "diff/operation", "operation must equal the direct typed delta")); } Ok(()) }
pub async fn apply_diff(diff: &GltfMoveAnimationDiff, base: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_diff(diff, base)?; let mut next = base.clone(); let operation = &diff.operation; match operation { GltfMoveAnimationOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Animations, &Change::Insert(*position))?; next.document.animations.insert(*position, item.clone());  }, GltfMoveAnimationOperation::Delete { index, .. } => { animations_op(&mut next, GltfTopLevelFamily::Animations, *index, None, None)?;  }, GltfMoveAnimationOperation::Move { index, position } => { animations_op(&mut next, GltfTopLevelFamily::Animations, *index, Some(*position), None)?;  }, GltfMoveAnimationOperation::Reorder { order } => { animations_op(&mut next, GltfTopLevelFamily::Animations, order[0], None, Some(order))?;  } } Ok(next) }
pub async fn encode(diff: &GltfMoveAnimationDiff) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(diff).map_err(|error| reject("gltf.mutation.encode-failed", "diff", error.to_string())) }
pub async fn derive(payload: &GltfMoveAnimationPayload, base: &GltfSnapshot) -> Result<GltfMoveAnimationDiff, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfMoveAnimationDiff { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
pub async fn derive_transitional_gltf_diff(payload: &GltfMoveAnimationPayload, base: &GltfSnapshot) -> Result<GltfDiff, GltfTopLevelMutationRejection> { let next = apply(payload, base)?; Ok(family_diff(GltfTopLevelFamily::Animations, base, &next)) }
